"""Render measured fresh/reference results from archived verification."""
import json,html
from pathlib import Path
R=Path(__file__).resolve().parent
read=lambda n:json.loads((R/n).read_text())
v=read('verification.json');c=read('outcome-tables.json')['counts']
lanes=[('Node JavaScript','node||prior_over_checked_js'),('Browser JavaScript','browser||prior_over_checked_js'),('Node WebAssembly','node||prior_over_checked_wasm'),('Browser WebAssembly','browser||prior_over_checked_wasm'),('Native C · resident','native|resident|prior_over_checked'),('Native C · copied inputs','native|snapshot|prior_over_checked')]
rows=''
for label,key in lanes:
 d=c.get('fresh|'+key+'|all',{})
 rows+=f"<tr><td>{html.escape(label)}</td><td class=win>{d.get('faster',0)}</td><td class=loss>{d.get('slower',0)}</td><td>{d.get('inconclusive',0)}</td></tr>"
def expert(key):return sum(c.get(role+'|'+key+'|all',{}).get('Ink_faster',0) for role in ['fresh','reference'])
nr=expert('native|resident|checked_over_rust_expert');ns=expert('native|snapshot|checked_over_rust_expert');gpu=expert('browser||js_expert_over_ink_checked_gpu')
text=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Ink · checked proof batch 22</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#10181d;color:#dce9ed;font:15px system-ui,sans-serif}}main{{max-width:1000px;margin:auto;padding:28px 38px}}small{{color:#95aeb8;letter-spacing:.1em}}h1{{font-size:32px;margin:12px 0}}p{{line-height:1.5;color:#bbced6;margin:10px 0}}.cards{{display:flex;gap:12px;margin:18px 0}}.card{{flex:1;border:1px solid #344951;padding:12px 16px;border-radius:8px;background:#17232a}}.card strong{{display:block;font-size:25px;color:#f0faf9}}.card span{{font-size:13px;color:#9fb8c0}}table{{width:100%;border-collapse:collapse;margin:14px 0}}th,td{{text-align:right;padding:8px 12px;border-bottom:1px solid #2b3e48}}th:first-child,td:first-child{{text-align:left}}th{{font-size:12px;color:#97adb7}}.win{{color:#86dfb7}}.loss{{color:#f5a09a}}.notice{{border-left:3px solid #e6b35a;background:#242c2d;padding:10px 16px}}.foot{{font-size:12px;color:#98aeb6}}a{{color:#9ed8ef}}h2{{font-size:18px;margin:20px 0 6px}}
</style><main><small>INK / CHECKED WEB-STACK PROOFS / BATCH 22</small><h1>Guard merging and indexed self-zip fusion</h1><p>General equalities for arbitrary pure callbacks and finite lists.<br>Compile-time proof application; no runtime optimizer or caller checks added.</p><div class=cards><div class=card><strong>15</strong><span>generic optimization endpoints</span></div><div class=card><strong>{v['catalog_entries']:,}</strong><span>proof objects · fair prior {v['fair_prior_entries']:,}</span></div><div class=card><strong>{v['timing_samples']:,}</strong><span>samples · {v['exact_benchmark_comparisons']:,} complete comparisons</span></div></div><h2>Fresh recipes versus fair prior · 48 cells per row</h2><p class=foot>Eight fresh recipes; four complementary guard references have identical selected bodies.<br>Individual paired 95% intervals; all {v['regressions_retained']} fresh regressions retained.</p><table><thead><tr><th>Target and call boundary</th><th>Faster</th><th>Slower</th><th>Inconclusive</th></tr></thead><tbody>{rows}</tbody></table><div class=notice><strong>Broad superiority over optimized handwritten code remains unproven.</strong><p>Native Ink wins {nr}/72 resident and {ns}/72 copied-input cells against expert Rust.<br>Indexed WebGPU wins {gpu}/36 against expert JS with transfers included.</p></div><p class=foot>Six indexed recipes emit actual shaders; scalar recipes fall back. No handwritten WGSL expert.<br>One machine, preset U32 workloads. Parameters vary with size; no general language ranking.</p><p class=foot>{v['canonical_observations']:,} canonical observations · 48 checked selection packages · 102 unchanged source guards.<br>{v['web_intervals_independently_recomputed']+v['native_intervals_independently_recomputed']:,} independently recomputed intervals. Supports, deployments and old consequences counted separately.</p><p class=foot><a href="REPORT.md">Full report and proof sketches</a> · <a href="outcome-tables.json">All outcomes</a> · <a href="fresh-regressions.json">Every regression</a> · <a href="verification.json">Verification</a></p></main></html>'''
(R/'browser-completed.html').write_text(text)
